const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

/**
 * An icon as SVG markup, for pages without a framework. Decorative (hidden
 * from screen readers) unless it is given a label, which an icon alone needs.
 */
export function iconSvg(name, { label, className = 'ds-icon' } = {}) {
  const nodes = icons[name];
  if (!nodes) throw new Error(`no icon called ${name}`);
  const frame = Object.entries(iconFrame).map(([k, v]) => ` ${k}="${v}"`).join('');
  const a11y = label ? ` role="img" aria-label="${esc(label)}"` : ' aria-hidden="true" focusable="false"';
  const body = nodes.map(([tag, a]) => `<${tag}${Object.entries(a).map(([k, v]) => ` ${k}="${v}"`).join('')}/>`).join('');
  return `<svg class="${esc(className)}"${frame}${a11y}>${body}</svg>`;
}
